/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: code, projects, albums, manifest, album, revisionOf, albumDecision
 *   Constants: actor, ordinary, by
 *   Variables: harness
 * Tests
 *   - a create for an Album stores reuse of that Album at its current revision and its title as the administrator's own, and replays its receipt
 *   - a create without a target keeps its fingerprint and stores no target
 *   - a retry naming another Album, or none, under the same operation conflicts instead of replaying
 *   - a create for an Album refuses a missing, not ready or malformed Album, one without a primary Artist Credit, one crediting a primary Artist that is not ready and one over the member bound, writing nothing
 *   - an import whose Album decision is reuse lists that Album as a candidate whatever the draft title, once, and a stale reuse can be chosen again
 *   - an import created for an Album keeps listing that Album after its title changes and its Album decision is create-distinct, and can reuse it again
 *   - an import not created for an Album, with an Album decision other than reuse, lists no Album whose title differs
 *   - the Album target read names the title, ready primary Artists, cover and missing-file rows, and each refusal
 * @end-catalog */

import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { after, before, beforeEach, test } from 'node:test';
import { ObjectId } from 'mongodb';
import { getDb } from '../../src/infrastructure/database';
import { startMongoReplicaSet, type MongoReplicaSetHarness } from '../support/mongoReplicaSet';
import { AdminImportError, parseManifest } from '../../src/administration/import/adminImportContract';
import {
    adminImportDuplicateCandidates, createAdminImport, decideAdminImportDuplicates, getAdminImportAlbumTarget, importCandidateProjection, importCandidateRevision, importCreateHash,
    initializeAdminImportStorage, type AdminImportDocument
} from '../../src/administration/import/adminImportService';
import { getAdminImportLookup } from '../../src/administration/lookup/metadataLookupRequests';
import { editImportDraft } from '../support/adminImportDraftChanges';
import { expectedTracklistForStorage } from '../../src/services/catalog/albumExpectedTracklist';

let harness: MongoReplicaSetHarness; const actor = new ObjectId(), ordinary = new ObjectId(), by = actor.toHexString();
const code = (expected: string) => (error: unknown) => error instanceof AdminImportError && error.code === expected;
const projects = () => getDb()!.collection<AdminImportDocument>('adminAlbumImports');
const albums = () => getDb()!.collection('albums');
const manifest = () => ({ rootLabel: 'Synthetic Folder', files: [{ slotId: randomUUID(), filename: '07 - Song.mp3', relativePath: 'Disc 1/07 - Song.mp3', byteLength: 123 }] });
/** A ready Album credited to one ready primary Artist (or the given Credits), with `members` declared member IDs. */
async function album(extra: Record<string, unknown> = {}) {
    const albumId = new ObjectId(), artistId = new ObjectId();
    await getDb()!.collection('artists').insertOne({ _id: artistId, name: 'Synthetic Ensemble', lifecycleStatus: 'ready', visibility: 'public' });
    await albums().insertOne({ _id: albumId, title: 'Synthetic Existing Album', visibility: 'public', lifecycleStatus: 'ready', audioTrackIds: [],
        credits: [{ creditId: 'primary_artist', subjectType: 'artist', subjectId: String(artistId), role: 'primary', order: 0 }], attributionStatus: 'documented', ...extra });
    return { albumId: albumId.toHexString(), artistId: artistId.toHexString() };
}
/** The Album's candidate revision, as an Album decision binds it. */
const revisionOf = async (albumId: string) => importCandidateRevision((await albums().findOne({ _id: new ObjectId(albumId) }, { projection: importCandidateProjection }))!);
const albumDecision = (candidateId: string, candidateRevision: string) => ({ scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'reuse', candidateId, candidateRevision });

before(async () => { harness = await startMongoReplicaSet('archtree-admin-import-album-target-test'); });
beforeEach(async () => {
    process.env.FINITUDE_ADMIN_IMPORTS_ENABLED = 'true'; const db = getDb()!;
    for (const name of ['users', 'adminAlbumImports', 'adminImportLookups', 'artists', 'organizations', 'albums', 'audioTracks']) await db.collection(name).deleteMany({});
    await db.collection('users').insertMany([{ _id: actor, email: 'album-target@example.test', role: 'admin' }, { _id: ordinary, email: 'album-target-user@example.test', role: 'user' }]);
    await initializeAdminImportStorage(db);
});
after(async () => { delete process.env.FINITUDE_ADMIN_IMPORTS_ENABLED; await harness?.stop(); });

test('a create for an Album stores reuse of that Album at its current revision and its title as the administrator\'s own, and replays its receipt', async () => {
    const { albumId } = await album(), body = { operationId: randomUUID(), manifest: manifest(), targetAlbumId: albumId };
    const [first, second] = await Promise.all([createAdminImport(by, body), createAdminImport(by, body)]);
    assert.equal(first.item.id, second.item.id);
    const doc = (await projects().findOne({ _id: new ObjectId(first.item.id) }))!;
    assert.deepEqual(doc.decisions, [{ scope: 'album', slotId: null, action: 'reuse', candidateId: albumId, candidateRevision: await revisionOf(albumId), entryKey: null, boundName: null }]);
    assert.deepEqual([doc.createdForAlbumId, (doc.draft as { album: { title: string } }).album.title, doc.draftOrigins], [albumId, 'Synthetic Existing Album', { 'album:title': 'administrator' }]);
    assert.equal(doc.receipts[0].hash, importCreateHash(parseManifest(body.manifest), undefined, body.operationId, albumId));
    assert.equal(first.item.decisions[0].candidateId, albumId);
    // A replay needs neither the Album nor admission.
    await albums().deleteMany({}); delete process.env.FINITUDE_ADMIN_IMPORTS_ENABLED;
    assert.equal((await createAdminImport(by, body)).item.id, first.item.id);
    assert.equal(await projects().countDocuments(), 1);
});

test('a create without a target keeps its fingerprint and stores no target', async () => {
    const body = { operationId: randomUUID(), manifest: manifest() }, created = await createAdminImport(by, body);
    const doc = (await projects().findOne({ _id: new ObjectId(created.item.id) }))!;
    assert.equal(doc.receipts[0].hash, importCreateHash(parseManifest(body.manifest), undefined, body.operationId));
    assert.deepEqual([doc.decisions, 'createdForAlbumId' in doc, (doc.draft as { album: { title: string } }).album.title], [[], false, '']);
    assert.equal((await getAdminImportLookup(by, created.item.id)).summary.forAlbum, undefined);
});

test('a retry naming another Album, or none, under the same operation conflicts instead of replaying', async () => {
    const first = await album(), second = await album(), body = { operationId: randomUUID(), manifest: manifest() };
    await createAdminImport(by, { ...body, targetAlbumId: first.albumId });
    await assert.rejects(createAdminImport(by, { ...body, targetAlbumId: second.albumId }), code('ADMIN_IMPORT_OPERATION_CONFLICT'));
    await assert.rejects(createAdminImport(by, body), code('ADMIN_IMPORT_OPERATION_CONFLICT'));
    const plain = { operationId: randomUUID(), manifest: manifest() };
    await createAdminImport(by, plain);
    await assert.rejects(createAdminImport(by, { ...plain, targetAlbumId: first.albumId }), code('ADMIN_IMPORT_OPERATION_CONFLICT'));
    assert.equal(await projects().countDocuments(), 2);
});

test('a create for an Album refuses a missing, not ready or malformed Album, one without a primary Artist Credit, one crediting a primary Artist that is not ready and one over the member bound, writing nothing', async () => {
    const create = (targetAlbumId: unknown, extra: Record<string, unknown> = {}) => createAdminImport(by, { operationId: randomUUID(), manifest: manifest(), targetAlbumId, ...extra });
    await assert.rejects(create(new ObjectId().toHexString()), code('ADMIN_IMPORT_TARGET_UNAVAILABLE'));
    await assert.rejects(create((await album({ lifecycleStatus: 'deleting' })).albumId), code('ADMIN_IMPORT_TARGET_UNAVAILABLE'));
    await assert.rejects(create((await album({ visibility: 'weird' })).albumId), code('ADMIN_IMPORT_TARGET_UNAVAILABLE'));
    await assert.rejects(create((await album({ title: '' })).albumId), code('ADMIN_IMPORT_TARGET_UNAVAILABLE'));
    // Approval would refuse a primary Artist that is not ready, so creation names that refusal up front.
    const notReady = await album();
    await getDb()!.collection('artists').updateOne({ _id: new ObjectId(notReady.artistId) }, { $set: { lifecycleStatus: 'deleteFailed' } });
    await assert.rejects(create(notReady.albumId), code('ADMIN_IMPORT_TARGET_UNAVAILABLE'));
    assert.equal((await getAdminImportAlbumTarget(by, notReady.albumId)).refusal, 'primaryNotReady');
    await assert.rejects(create((await album({ credits: [] })).albumId), code('ADMIN_IMPORT_APPEND_PRIMARY_REQUIRED'));
    await assert.rejects(create((await album({ credits: null })).albumId), code('ADMIN_IMPORT_APPEND_PRIMARY_REQUIRED'));
    const many = Array.from({ length: 5001 }, () => new ObjectId().toHexString());
    await assert.rejects(create((await album({ audioTrackIds: many })).albumId), code('ADMIN_IMPORT_TARGET_TOO_LARGE'));
    await assert.rejects(create((await album({ audioTrackIds: 'not-a-list' })).albumId), code('ADMIN_IMPORT_TARGET_TOO_LARGE'));
    const { albumId } = await album();
    for (const malformed of ['not-an-id', albumId.toUpperCase(), null, 7]) await assert.rejects(create(malformed), code('ADMIN_IMPORT_INVALID_INPUT'));
    await assert.rejects(create(albumId, { draft: { album: { title: '', artistName: '', releaseDate: null, visibility: 'hidden' }, tracks: [] } }), code('ADMIN_IMPORT_INVALID_INPUT'));
    // Admission comes before the target check: with imports disabled even a missing Album is refused as disabled.
    delete process.env.FINITUDE_ADMIN_IMPORTS_ENABLED;
    await assert.rejects(create(new ObjectId().toHexString()), code('ADMIN_IMPORTS_DISABLED'));
    assert.equal(await projects().countDocuments(), 0);
});

test('an import whose Album decision is reuse lists that Album as a candidate whatever the draft title, once, and a stale reuse can be chosen again', async () => {
    const { albumId } = await album(), created = await createAdminImport(by, { operationId: randomUUID(), manifest: manifest(), targetAlbumId: albumId });
    const listed = async () => (await adminImportDuplicateCandidates(by, created.item.id)).items.filter(item => item.kind === 'album');
    // The draft title matches the Album at first: it is listed once, by name.
    assert.deepEqual((await listed()).map(item => [item.id, item.match, item.revision]), [[albumId, 'name', await revisionOf(albumId)]]);
    const renamed = await editImportDraft(by, created.item.id, created.item, draft => { draft.album.title = 'Another Synthetic Title'; });
    assert.deepEqual((await listed()).map(item => [item.id, item.match]), [[albumId, 'name']]);
    const answers = (await getAdminImportLookup(by, created.item.id)).summary.identityAnswers;
    // The Album changes after it was chosen: it is listed at its new revision, the saved revision is stale, and choosing it again works.
    const before = await revisionOf(albumId);
    await albums().updateOne({ _id: new ObjectId(albumId) }, { $set: { releaseDate: { year: 2001 } } });
    const after = await revisionOf(albumId);
    assert.notEqual(after, before);
    assert.deepEqual((await listed()).map(item => [item.id, item.revision]), [[albumId, after]]);
    await assert.rejects(decideAdminImportDuplicates(by, created.item.id, { operationId: randomUUID(), expectedRevision: renamed.item.revision, decisions: [albumDecision(albumId, before)] }),
        code('ADMIN_IMPORT_DUPLICATE_STALE'));
    const chosen = await decideAdminImportDuplicates(by, created.item.id, { operationId: randomUUID(), expectedRevision: renamed.item.revision, decisions: [albumDecision(albumId, after)] });
    assert.equal(chosen.item.decisions[0].candidateRevision, after);
    assert.equal((await getAdminImportLookup(by, created.item.id)).summary.identityAnswers, answers);
    assert.equal((await getAdminImportLookup(by, created.item.id)).summary.forAlbum, albumId);
});

test('an import created for an Album keeps listing that Album after its title changes and its Album decision is create-distinct, and can reuse it again', async () => {
    const { albumId } = await album(), created = await createAdminImport(by, { operationId: randomUUID(), manifest: manifest(), targetAlbumId: albumId });
    const renamed = await editImportDraft(by, created.item.id, created.item, draft => { draft.album.title = 'Another Synthetic Title'; });
    const distinct = await decideAdminImportDuplicates(by, created.item.id, { operationId: randomUUID(), expectedRevision: renamed.item.revision,
        decisions: [{ scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'create-distinct', candidateId: null, candidateRevision: null }] });
    const listed = async () => (await adminImportDuplicateCandidates(by, created.item.id)).items.filter(item => item.kind === 'album').map(item => [item.id, item.match]);
    assert.deepEqual(await listed(), [[albumId, 'name']]);
    const again = await decideAdminImportDuplicates(by, created.item.id, { operationId: randomUUID(), expectedRevision: distinct.item.revision, decisions: [albumDecision(albumId, await revisionOf(albumId))] });
    assert.equal(again.item.decisions[0].candidateId, albumId);
    assert.deepEqual(await listed(), [[albumId, 'name']]);
});

test('an import not created for an Album, with an Album decision other than reuse, lists no Album whose title differs', async () => {
    await album();
    const created = await createAdminImport(by, { operationId: randomUUID(), manifest: manifest() });
    const titled = await editImportDraft(by, created.item.id, created.item, draft => { draft.album.title = 'Another Synthetic Title'; });
    await decideAdminImportDuplicates(by, created.item.id, { operationId: randomUUID(), expectedRevision: titled.item.revision,
        decisions: [{ scope: 'album', slotId: null, entryKey: null, boundName: null, action: 'create-distinct', candidateId: null, candidateRevision: null }] });
    assert.deepEqual((await adminImportDuplicateCandidates(by, created.item.id)).items.filter(item => item.kind === 'album'), []);
});

test('the Album target read names the title, ready primary Artists, cover and missing-file rows, and each refusal', async () => {
    const { albumId, artistId } = await album({ coverArtUrl: '/content/images/' + 'a'.repeat(24) }), second = new ObjectId(), hiddenAway = new ObjectId(), memberId = new ObjectId();
    await getDb()!.collection('artists').insertMany([{ _id: second, name: 'Second Synthetic Artist', lifecycleStatus: 'ready' }, { _id: hiddenAway, name: 'Deleting Artist', lifecycleStatus: 'deleting' }]);
    const tracklist = expectedTracklistForStorage('musicbrainz', new Date('2026-10-01T00:00:00.000Z'), [1, 2, 3].map(trackNumber => ({ discNumber: 1, trackNumber, title: `Row ${trackNumber}`, durationMs: null })));
    assert.ok(tracklist.ok);
    await getDb()!.collection('audioTracks').insertOne({ _id: memberId, title: 'Row 2', albumId, trackNumber: 2, uploadStatus: 'ready', s3Key: String(memberId), mediaType: 'audio' });
    await albums().updateOne({ _id: new ObjectId(albumId) }, { $set: { audioTrackIds: [String(memberId)], expectedTracklist: tracklist.tracklist, credits: [
        { creditId: 'second_artist', subjectType: 'artist', subjectId: String(second), role: 'primary', order: 0 },
        { creditId: 'deleting_artist', subjectType: 'artist', subjectId: String(hiddenAway), role: 'primary', order: 1 },
        { creditId: 'primary_artist', subjectType: 'artist', subjectId: artistId, role: 'primary', order: 2 }] } });
    // A primary Artist that is not ready refuses the Album; the card still names the ready ones.
    assert.deepEqual(await getAdminImportAlbumTarget(by, albumId), { albumId, refusal: 'primaryNotReady', album: { title: 'Synthetic Existing Album', primaryArtists: ['Second Synthetic Artist', 'Synthetic Ensemble'],
        coverUrl: `/api/admin/v1/catalog/album/${albumId}/artwork`, missingRows: 2 } });
    await getDb()!.collection('artists').updateOne({ _id: hiddenAway }, { $set: { lifecycleStatus: 'ready' } });
    assert.deepEqual(await getAdminImportAlbumTarget(by, albumId), { albumId, refusal: null, album: { title: 'Synthetic Existing Album', primaryArtists: ['Second Synthetic Artist', 'Deleting Artist', 'Synthetic Ensemble'],
        coverUrl: `/api/admin/v1/catalog/album/${albumId}/artwork`, missingRows: 2 } });
    const plain = await album();
    assert.deepEqual(await getAdminImportAlbumTarget(by, plain.albumId), { albumId: plain.albumId, refusal: null, album: { title: 'Synthetic Existing Album', primaryArtists: ['Synthetic Ensemble'], coverUrl: null, missingRows: null } });
    const missing = new ObjectId().toHexString();
    assert.deepEqual(await getAdminImportAlbumTarget(by, missing), { albumId: missing, refusal: 'unavailable', album: null });
    for (const extra of [{ title: '' }, { title: 'Bad\u0007Title' }, { visibility: 'weird' }]) {
        const unreadable = await album(extra);
        assert.deepEqual(await getAdminImportAlbumTarget(by, unreadable.albumId), { albumId: unreadable.albumId, refusal: 'unreadable', album: null }, JSON.stringify(extra));
    }
    const unattributed = await album({ credits: [] }), large = await album({ audioTrackIds: Array.from({ length: 5001 }, () => new ObjectId().toHexString()), expectedTracklist: tracklist.tracklist });
    assert.deepEqual([(await getAdminImportAlbumTarget(by, unattributed.albumId)).refusal, (await getAdminImportAlbumTarget(by, unattributed.albumId)).album?.primaryArtists], ['primaryRequired', []]);
    assert.deepEqual([(await getAdminImportAlbumTarget(by, large.albumId)).refusal, (await getAdminImportAlbumTarget(by, large.albumId)).album?.missingRows], ['tooLarge', null]);
    // The read works while imports are disabled; a malformed ID and an ordinary user are refused.
    delete process.env.FINITUDE_ADMIN_IMPORTS_ENABLED;
    assert.equal((await getAdminImportAlbumTarget(by, plain.albumId)).refusal, null);
    await assert.rejects(getAdminImportAlbumTarget(by, 'not-an-id'), code('ADMIN_IMPORT_INVALID_INPUT'));
    await assert.rejects(getAdminImportAlbumTarget(ordinary.toHexString(), plain.albumId), code('ADMIN_IMPORT_ADMIN_REQUIRED'));
});
